const BuzzerAudioSample* BuzzerAudioSamples::find(const char* soundId) {
  if (soundId == nullptr || *soundId == '\0') return nullptr;
  for (const BuzzerAudioSample* sample : SAMPLES) {
    if (std::strcmp(sample->soundId, soundId) == 0) return sample;
  }
  return BuzzerAudioSamplesExtra::find(soundId);
}

size_t BuzzerAudioSamples::count() {
  return (sizeof(SAMPLES) / sizeof(SAMPLES[0])) + BuzzerAudioSamplesExtra::count();
}

